contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        uint256 beforeCallerBalance = address(this).balance;
        uint256 beforeContractBalance = address(c).balance;

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositCallerBalance = address(this).balance;

        c.refund(); if (__ESBMC_reverted()) return;

        uint256 afterRefundContractBalance = address(c).balance;
        uint256 afterRefundCallerBalance = address(this).balance;

        assert(
            afterDepositContractBalance == beforeContractBalance + depositAmount &&
            afterDepositCallerBalance == beforeCallerBalance - depositAmount &&
            afterRefundContractBalance == beforeContractBalance &&
            afterRefundCallerBalance == beforeCallerBalance
        );
    }
}

