// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        uint256 beforeCallerBalance = address(this).balance;
        uint256 beforeContractBalance = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositCallerBalance = address(this).balance;
        try c.refund() {} catch { return; }
        uint256 afterRefundContractBalance = address(c).balance;
        uint256 afterRefundCallerBalance = address(this).balance;
        assertTrue(afterDepositContractBalance == beforeContractBalance + depositAmount &&
            afterDepositCallerBalance == beforeCallerBalance - depositAmount &&
            afterRefundContractBalance == beforeContractBalance &&
            afterRefundCallerBalance == beforeCallerBalance);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
